/**
 * Regression test for the setup .env merge.
 *
 * Setup can re-run against a directory that already holds a partial .env (that is
 * precisely what makes the process unconfigured). Previously the wizard replaced
 * the file wholesale, silently discarding any variable it does not manage.
 *
 * Exercised against the built output, like the other suites here.
 */
import test from 'node:test';
import assert from 'node:assert/strict';

const { mergeEnvContent } = await import('../packages/core/dist/setup.js');

const INCOMING = [
  '# generated by setup',
  'MCP_ENCRYPTION_KEY=new-key',
  'MCP_DB_PROVIDER=sqlite',
  'MCP_STORAGE_FILE=/data/mcp-ecc.db',
  'PORT=3001',
  '',
].join('\n');

test('setup merge: unmanaged variables from the existing file survive', () => {
  const existing = [
    '# hand written',
    'MCP_ENCRYPTION_KEY=old-key',
    'MCP_ENV_FILE=/etc/mcp-ecc/.env',
    'HOST=127.0.0.1',
    'SOME_CUSTOM_SETTING=keep-me',
    '',
  ].join('\n');

  const merged = mergeEnvContent(existing, INCOMING);

  // The wizard's value wins for a variable it manages.
  assert.match(merged, /^MCP_ENCRYPTION_KEY=new-key$/m);
  assert.ok(!merged.includes('old-key'), 'the superseded managed value must not survive');

  // Variables the wizard does not manage are preserved verbatim.
  assert.match(merged, /^MCP_ENV_FILE=\/etc\/mcp-ecc\/\.env$/m);
  assert.match(merged, /^HOST=127\.0\.0\.1$/m);
  assert.match(merged, /^SOME_CUSTOM_SETTING=keep-me$/m);

  // Still a usable dotenv: every preserved entry is a KEY=value line.
  for (const line of merged.split('\n')) {
    if (!line.trim() || line.startsWith('#')) continue;
    assert.match(line, /^[A-Za-z_][A-Za-z0-9_]*=/, `unexpected non-assignment line: ${line}`);
  }
});

test('setup merge: no unmanaged variables means the incoming content is used as-is', () => {
  const existing = 'MCP_ENCRYPTION_KEY=old-key\nPORT=9999\n';
  const merged = mergeEnvContent(existing, INCOMING);

  assert.equal(merged, INCOMING, 'nothing to preserve, so the file is regenerated cleanly');
  assert.ok(!merged.includes('9999'), 'the stale managed value must be gone');
});

test('setup merge: handles CRLF line endings in the existing file', () => {
  const existing = 'MCP_ENV_FILE=/data/.env\r\nCUSTOM=value\r\n';
  const merged = mergeEnvContent(existing, INCOMING);

  assert.ok(!merged.includes('\r'), 'carriage returns must not leak into the rewritten file');
  assert.match(merged, /^CUSTOM=value$/m);
});
